async () => {
 const id="__ID__",limit=__LIMIT__;
 const urls=[
  '/backend-api/conversation/'+id+'?num_turns='+limit+'&include_has_versions=true',
  '/backend-api/conversations/'+id+'?num_turns='+limit+'&include_has_versions=true'
 ];
 let accessToken;
 async function request(url,headers={}){
  const c=new AbortController(),timer=setTimeout(()=>c.abort(),9000);
  try{return await fetch(url,{credentials:'include',headers,cache:'no-store',signal:c.signal})}
  finally{clearTimeout(timer)}
 }
 async function token(){
  if(accessToken!==undefined)return accessToken;
  try{const a=await fetch('/api/auth/session',{credentials:'include'});accessToken=a.ok?(await a.json()).accessToken||null:null}
  catch{accessToken=null}
  return accessToken;
 }
 function messagesFromData(data){
  const mapping=data.mapping||{},nodes=[],seen=new Set();
  let node=data.current_node;
  while(typeof node==='string'&&mapping[node]&&!seen.has(node)){
   seen.add(node);nodes.push(mapping[node]);node=mapping[node].parent;
  }
  if(Array.isArray(data.messages))nodes.splice(0,nodes.length,...data.messages);
  else if(!nodes.length)nodes.push(...Object.values(mapping).reverse());else nodes.reverse();
  return nodes.map(n=>{const m=n?.message||n,role=m?.author?.role;
   if(role!=='user'&&role!=='assistant')return null;
   const parts=Array.isArray(m.content?.parts)?m.content.parts:[];
   const content=parts.map(x=>typeof x==='string'?x:typeof x?.text==='string'?x.text:'').filter(Boolean).join('\n').trim().slice(0,20000);
   return content?{role,content}:null}).filter(Boolean).slice(-limit);
 }
 function fromVisibleConversation(){
  if(location.pathname!=='/c/'+id)return null;
  const elements=Array.from(document.querySelectorAll('[data-message-author-role="user"],[data-message-author-role="assistant"]'));
  const messages=elements.map(el=>({role:el.getAttribute('data-message-author-role'),content:(el.innerText||'').trim().slice(0,20000)}))
   .filter(m=>m.content).slice(-limit);
  return messages.length?{id,conversationPath:'/c/'+id,messages,source:'browser-ui'}:null;
 }
 const visibleBeforeNetwork=fromVisibleConversation();
 if(visibleBeforeNetwork)return visibleBeforeNetwork;
 let lastStatus=404;
 for(const url of urls){
  try{
   let response=await request(url);
   if([401,403,404].includes(response.status)){
    const access=await token();
    if(access)response=await request(url,{authorization:'Bearer '+access});
   }
   lastStatus=response.status;
   if(response.status===404)continue;
   if(response.status===401||response.status===403)return {error:'LOGIN_REQUIRED'};
   if(!response.ok)continue;
   const data=await response.json();
   if(!data||typeof data!=='object'||(!data.mapping&&!Array.isArray(data.messages)))continue;
   return {id,conversationPath:'/c/'+id,messages:messagesFromData(data)};
  }catch(e){if(e?.name==='AbortError')lastStatus=408}
 }
 const visible=fromVisibleConversation();
 if(visible)return visible;
 return {error:lastStatus===404?'NOT_FOUND':'UNAVAILABLE',status:lastStatus};
}

