async () => {
 const ids=__IDS__;
 const current=/^\/c\/([0-9a-f-]{36})/i.exec(location.pathname)?.[1]?.toLowerCase();
 const streaming=!!document.querySelector('button[aria-label="Stop"],button[data-testid="stop-button"]');
 let accessToken;
 async function request(path) {
  async function attempt(headers={}){
   const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);
   try{return await fetch(path,{credentials:'include',headers,cache:'no-store',signal:ctrl.signal})}
   finally{clearTimeout(timer)}
  }
  let response=await attempt();
  if([401,403,404].includes(response.status)){
   if(accessToken===undefined) {
    const a=await fetch('/api/auth/session',{credentials:'include'});
    accessToken=a.ok?(await a.json()).accessToken||null:null;
   }
   if(accessToken)response=await attempt({authorization:'Bearer '+accessToken});
  }
  return response;
 }
 function deriveConversationStatus(data) {
  const mapping=data?.mapping||{};
  const node=typeof data?.current_node==='string'?mapping[data.current_node]:null;
  let message=node?.message||null;
  if(!message) {
   const nodes=Object.values(mapping);
   for(let i=nodes.length-1;i>=0;i--) if(nodes[i]?.message?.author?.role==='assistant'){message=nodes[i].message;break}
  }
  if(!message&&Array.isArray(data?.messages))message=data.messages[data.messages.length-1]?.message||data.messages[data.messages.length-1];
  if(!message || message.author?.role!=='assistant')return null;
  const status=message.status?.status||message.status;
  if(status==='in_progress'||status==='processing')return 'IN_PROGRESS';
  if(status==='failed'||status==='interrupted')return 'FAILED';
  if(status==='finished_successfully' && (message.end_turn===true||message.metadata?.is_complete===true))return 'COMPLETE';
  return null;
 }
 async function check(id) {
  if(current===id&&streaming)return {id,status:'in_progress',source:'browser-ui'};
  let streamPayload=null,reason='upstream_unavailable';
  try {
   const stream=await request('/backend-api/conversation/'+id+'/stream_status');
   if(stream.ok){
    try{
     const payload=await stream.json();
     if(payload&&typeof payload.status==='string'){
      const normalized=payload.status.toUpperCase();
      if(['COMPLETE','COMPLETED','FINISHED','FAILED','ERROR','ERRORED','INTERRUPTED','CANCELLED','CANCELED'].includes(normalized))streamPayload=payload;
      else return {id,payload};
     }else reason='missing_upstream_status';
    }catch{reason='invalid_upstream_status'}
   }else reason='upstream_http_'+stream.status;
  }catch(e){reason=e?.name==='AbortError'?'upstream_timeout':'upstream_network_error'}
  let verified=false,notFound=true;
  for(const base of ['/backend-api/conversation/','/backend-api/conversations/']){
   try{
    const response=await request(base+id+'?num_turns=2&include_has_versions=true');
    if(response.status!==404)notFound=false;
    if(!response.ok)continue;
    const data=await response.json();
    if(!data||typeof data!=='object'||(!data.mapping&&!Array.isArray(data.messages)))continue;
    verified=true;
    const derived=deriveConversationStatus(data);
    if(derived)return {id,payload:{status:derived}};
    if(streamPayload)return {id,payload:streamPayload};
    return {id,error:'insufficient_completion_evidence'};
   }catch(e){reason=e?.name==='AbortError'?'conversation_timeout':'conversation_fetch_failed'}
  }
  // An existing visible chat is positive evidence; an arbitrary ID is not.
  const visible=current===id && !!document.querySelector('[data-message-author-role="assistant"],[data-testid="conversation-turn-assistant"]');
  const sidebar=!!document.querySelector('a[href="/c/'+id+'"]');
  if(streamPayload && (visible||sidebar))return {id,payload:streamPayload};
  return {id,error:streamPayload?'unverified_terminal_status':notFound?'not_found':reason};
 }
 const output=new Array(ids.length);
 let cursor=0;
 await Promise.all(Array.from({length:Math.min(6,ids.length)},async()=>{
  while(cursor<ids.length){const i=cursor++;output[i]=await check(ids[i])}
 }));
 return {results:output};
}

