 if(location.pathname!==path)return {error:'UNAVAILABLE'};
 const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
 for(let i=0;i<45;i++){
  const text=(document.body?.innerText||'').slice(0,10000);
  if(/could not load this chatgpt conversation|conversation not found|unable to load conversation/i.test(text))
   return {error:'NOT_FOUND'};
