async () => {
 const prompt=__PROMPT__,targetPath=__PATH__;
 const sleep=ms=>new Promise(r=>setTimeout(r,ms));
 if(!document.querySelector('button[aria-label="Open profile menu"]')) {
  const a=await fetch('/api/auth/session',{credentials:'include'}).catch(()=>null);
  if(!a?.ok)return {error:'LOGIN_REQUIRED'};
  const s=await a.json().catch(()=>({}));if(!s.accessToken)return {error:'LOGIN_REQUIRED'};
 }
 let editor=null;
 for(let i=0;i<80;i++){editor=document.querySelector('[contenteditable="true"][role="textbox"],#prompt-textarea,[data-testid="prompt-textarea"],[contenteditable="true"],textarea[placeholder]');if(editor)break;await sleep(200)}
 if(!editor)return {error:'NO_COMPOSER'};
 if(targetPath && location.pathname!==targetPath)return {error:'WRONG_CONVERSATION'};
 const headings=()=>{const turns=Array.from(document.querySelectorAll('[data-message-author-role=assistant],[data-testid=conversation-turn-assistant]'));return turns.length?turns:Array.from(document.querySelectorAll('*')).filter(e=>e.children.length===0&&e.textContent?.trim()==='ChatGPT said:')};
 const before=headings().length;
 editor.focus();
 if(editor.isContentEditable){document.execCommand('selectAll',false,null);document.execCommand('insertText',false,prompt)}
 else{const setter=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value')?.set;if(setter)setter.call(editor,prompt);else editor.value=prompt;editor.dispatchEvent(new Event('input',{bubbles:true}))}
 await sleep(180);
 let send=document.querySelector('button[data-testid="send-button"],button[aria-label="Send prompt"],button[aria-label="Send message"]');
 if(send&&!send.disabled)send.click();else editor.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',keyCode:13,which:13,bubbles:true,cancelable:true}));
 let started=Date.now(),sawStop=false,firstReply=0,prev='',stable=0,found=false;
 while(Date.now()-started<110000){
  const stop=!!document.querySelector('button[aria-label="Stop"],button[data-testid="stop-button"]');if(stop)sawStop=true;
  const h=headings();if(h.length>before){found=true;if(!firstReply)firstReply=Date.now()}
  if(found){const node=h[h.length-1];const message=((node.matches?.('[data-message-author-role=assistant],[data-testid=conversation-turn-assistant]')?node.innerText:node.parentElement?.parentElement?.innerText)||'').replace(/^ChatGPT said:\s*/,'').trim();
   if(message&&message===prev)stable++;else stable=0;prev=message;
   if(message&&!stop&&((sawStop&&stable>=2)||(!sawStop&&stable>=5&&Date.now()-firstReply>=2600)))
    return {reply:message,conversationPath:location.pathname.startsWith('/c/')?location.pathname:null}
  }
  await sleep(200);
 }
 return {error:found?'RESPONSE_TIMEOUT':'NO_RESPONSE'};
}
